        catch (Exception e) {
            // Failed to run selected animation
        }
    }

    void runGreetingAnimation() {
        try {
            int animationID = Integer.parseInt(greetingJSpinner.getValue().toString());
            this.animatedNPC.setAnimation(animationID);
