            // Failed to stop the NPC animation
        }
    }

    void buildGreetingsContainer() {
        buildGreetingsComponents();
        buildFooterContainer();

        GridLayout layout = new GridLayout();
        layout.setRows(4);
        layout.setColumns(1);
        layout.setVgap(5);
        this.greetingsContainer.setLayout(layout);
